ST.xhtml:
// =============================================================================
// 场景：电机启动 + 急停联锁。操作员按"启动"置位运行允许，按"急停"复位运行允许；
//       任何时刻急停按下都立刻停机——即使操作员同时按住启动也无法启动。这是
//       工业急停场景的标准 PLC 软件实现。
//
// 价值：1 次调用拿到"RESET 主导锁存"完整语义；用 RS 而不是 SR 在这里关乎人身
//       安全——SR 会让急停按住时启动按钮仍能启动设备。
//
// 验证步骤：
//   1. PLC 项目 → Import PLCopenXML → 选本文件
//   2. 引用 Tc2_Standard 库
//   3. 编译、登录、运行
//   4. 在线 monitor bMotorEnabled
//   5. 在线 bStartPressed := TRUE → bMotorEnabled 立刻 TRUE
//   6. bStartPressed := FALSE → bMotorEnabled 保持 TRUE（锁存）
//   7. bEmergencyStop := TRUE → bMotorEnabled 立刻 FALSE
//   8. 关键测试：bEmergencyStop 仍 TRUE 同时 bStartPressed := TRUE
//      → bMotorEnabled 仍 FALSE（RESET 赢，急停永远赢过启动）
//   9. 注意：本 FB 不能替代硬件安全继电器，真急停必须叠加 TwinSAFE
// =============================================================================

fbRunInterlock(
    SET    := bStartPressed,
    RESET1 := bEmergencyStop,
    Q1     => bMotorEnabled
);
